<script setup lang="ts">
import { ref, computed,watch,onBeforeUnmount } from 'vue'
import { cloneJson } from '../render/clone'
import { themeList,getTheme } from '../render/design'
import { PALETTE_KEYS,SIZE_KEYS,BULLET_MARKERS,type ThemeOverrides } from '../render/themeOverrides'
import type { Project } from '@/types/aippt'
import type {ThemeDraft} from '@/composables/aippt/useThemeSaveQueue'
const props=defineProps<{project:Project;disabled?:boolean;save?:(value:ThemeDraft,retry?:boolean)=>Promise<Project>;rebase?:()=>Promise<Project>;status?:string;saveError?:string}>(),emit=defineEmits<{change:[id:string,overrides:ThemeOverrides|null];preview:[value:ThemeDraft]}>();const id=ref(props.project.theme_id),draft=ref<ThemeOverrides>(cloneJson(props.project.theme_overrides||{})),dirty=ref(false),error=ref('');let epoch=0,timer:ReturnType<typeof setTimeout>|undefined,inflight:Promise<void>|null=null,sentEpoch=-1
const base=computed(()=>getTheme(id.value));watch(()=>[props.project.id,props.project.theme_id,props.project.theme_revision,props.project.theme_overrides] as const,(value,previous)=>{if(value[0]!==previous[0]||!dirty.value){clearTimeout(timer);epoch++;id.value=props.project.theme_id;draft.value=cloneJson(props.project.theme_overrides||{});dirty.value=false;error.value=''}},{deep:true})
function touch(){dirty.value=true;epoch++;error.value='';emit('preview',{project_id:props.project.id,theme_id:id.value,theme_overrides:cloneJson(draft.value)});clearTimeout(timer);timer=setTimeout(()=>{void save(false).catch(()=>{})},320)}
function color(key:string,value:string|null){draft.value.palette={...draft.value.palette,[key]:value||base.value.palette[key as keyof typeof base.value.palette]};touch()}
function size(key:string,value:number|undefined){draft.value.text_styles={...draft.value.text_styles,[key]:{size_pt:value}};touch()}
function shape(key:string,value:unknown){draft.value.shape={...draft.value.shape,[key]:value};touch()}
async function save(retry=true){clearTimeout(timer);if(sentEpoch===epoch&&inflight)return inflight;const own=epoch,pid=props.project.id,value:ThemeDraft={project_id:pid,theme_id:id.value,theme_overrides:cloneJson(draft.value)};sentEpoch=own;const work=(async()=>{try{if(props.save)await props.save(value,retry);else emit('change',value.theme_id,value.theme_overrides);if(own===epoch&&pid===props.project.id){dirty.value=false;error.value=''}}catch(e:any){if(own===epoch&&pid===props.project.id)error.value=e.message;throw e}})();inflight=work;try{await work}finally{if(inflight===work)inflight=null}}
async function flush(){clearTimeout(timer);if(dirty.value)await save(false);else if(inflight)await inflight}
async function rebase(){if(!props.rebase)return;const own=epoch,pid=props.project.id;try{await props.rebase();if(own===epoch&&pid===props.project.id){dirty.value=false;error.value=''}}catch(e:any){if(pid===props.project.id)error.value=e.message}}
function reset(){draft.value={};touch()}
defineExpose({flush,isDirty:()=>dirty.value,copy:()=>({project_id:props.project.id,theme_id:id.value,theme_overrides:cloneJson(draft.value)})})
onBeforeUnmount(()=>clearTimeout(timer))
</script>
<template><el-form label-position="top" :disabled="disabled"><el-form-item label="主题"><el-select v-model="id" @change="draft={};touch()"><el-option v-for="t in themeList" :key="t.id" :value="t.id" :label="t.name"/></el-select></el-form-item><el-form-item v-for="c in PALETTE_KEYS" :key="c.key" :label="c.label"><el-color-picker :model-value="draft.palette?.[c.key]||base.palette[c.key]" @change="(v:any)=>color(c.key,v)"/><span>{{draft.palette?.[c.key]||base.palette[c.key]}}</span></el-form-item><el-form-item label="字体对"><el-select :model-value="draft.fonts?JSON.stringify(draft.fonts):JSON.stringify(base.fonts)" @change="(v:any)=>{draft.fonts=JSON.parse(v);touch()}"><el-option v-for="t in themeList" :key="t.id" :value="JSON.stringify(t.fonts)" :label="t.name+' · '+t.fonts.display.web+' / '+t.fonts.body.web"/></el-select><small>可用性取决于本机/Worker字体，缺失时质量报告会标记估算。</small></el-form-item><el-form-item v-for="s in SIZE_KEYS" :key="s.key" :label="s.label"><el-input-number :model-value="draft.text_styles?.[s.key]?.size_pt||base.text_styles[s.key].size_pt" :min="8" :max="72" @change="(v:any)=>size(s.key,v)"/></el-form-item><el-form-item label="圆角"><el-input-number :model-value="draft.shape?.radius_pt??base.shape.radius_pt" :min="0" :max="48" @change="(v:any)=>shape('radius_pt',v)"/></el-form-item><el-form-item label="要点符号"><el-select :model-value="draft.shape?.bullet_marker||base.shape.bullet_marker" @change="(v:any)=>shape('bullet_marker',v)"><el-option v-for="m in BULLET_MARKERS" :key="m.value" :value="m.value" :label="m.label"/></el-select></el-form-item><el-alert v-if="saveError||error" :title="saveError||error" type="error" :closable="false"/><p aria-live="polite">{{dirty?'主题预览尚未保存':status==='saving'?'主题保存中':'主题已保存'}}</p><el-button type="primary" @click="save().catch(()=>{})">{{saveError||error?'重试保存主题':'保存主题'}}</el-button><el-button v-if="status==='conflict'" @click="rebase">按最新版本重新应用主题</el-button><el-button @click="reset">重置微调</el-button></el-form></template>
<style scoped>.el-select{width:100%}small{color:#909399;display:block;line-height:1.5}</style>

